INSERT INTO `snipit_codes` (`id`, `snipit_id`, `html`, `css`, `javascript`, `created_at`, `updated_at`) VALUES
(1, 1, '<!DOCTYPE html>\r\n<html>\r\n\r\n<head>\r\n   <title>Delete Confirmation Message using JavaScript</title>\r\n   <script src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.3.1/jquery.min.js\"></script>\r\n</head>\r\n\r\n<body>\r\n <ul id=\"myList\">\r\n <li>Item 1 <button onclick=\"deleteItem(this)\">Delete</button></li>\r\n <li>Item 2 <button onclick=\"deleteItem(this)\">Delete</button></li>\r\n <li>Item 3 <button onclick=\"deleteItem(this)\">Delete</button></li>\r\n</ul>\r\n\r\n</body>\r\n\r\n</html>', NULL, 'function deleteItem(element) {\r\n   var listItem = element.parentNode;\r\n   var confirmDelete = confirm(\"Are you sure you want to delete this item?\");\r\n   if (confirmDelete) {\r\n     listItem.remove();\r\n   }\r\n }', '2024-10-25 17:45:35', '2024-10-25 18:12:13'),
(2, 2, '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n   <title>Count the number of characters in a string with space using jQuery</title>\r\n   <script src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.4.1/jquery.min.js\"></script>\r\n</head>\r\n\r\n<body>\r\n<h1>Count the number of characters in a string with space using jQuery</h1>\r\n<input type=\"text\" name=\"string\" value=\"welcome to w3coderschool\" class=\"input2\">\r\n<button class=\"clkbutton\">Click Me!</button>\r\n\r\n</body>\r\n</html>', NULL, '$(document).ready(function(){ \r\n   $(\'.clkbutton\').click(function(){\r\n   var countInput = $(\'.input2\').val().length;\r\n   alert(countInput);\r\n });\r\n});', '2024-10-25 18:46:38', '2024-10-25 18:59:43'),
(3, 3, '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n   <title>Count the number of characters in a string without space using jQuery</title>\r\n   <script src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.4.1/jquery.min.js\"></script>\r\n</head>\r\n\r\n<body>\r\n<h1>Count the number of characters in a string without space using jQuery</h1>\r\n<input type=\"text\" name=\"string\" value=\"welcome to w3coderschool\" class=\"input2\">\r\n<button class=\"clkbutton\">Click Me!</button>\r\n\r\n</body>\r\n</html>', NULL, '$(document).ready(function(){ \r\n   $(\'.clkbutton\').click(function(){\r\n   var countInput = $(\'.input2\').val().replace(/ /g,\'\').length;\r\n   alert(countInput);\r\n });\r\n});', '2024-10-25 18:53:09', '2024-10-25 19:00:14'),
(4, 4, '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n  <meta charset=\"UTF-8\" />\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  <title>Zoom an image on mouse hover by using CSS transform and scale property </title>\r\n\r\n</head>\r\n<body>\r\n  <div class=\"img-div\">\r\n    <img src=\"https://www.w3coderschool.com/attachments/file_1729864290.png\" alt=\"w3coderschool Image\" />\r\n  </div>\r\n</body>\r\n</html>', '.img-div {\r\n        margin: 0 auto;\r\n        width: 300px;\r\n        height: 300px;\r\n        overflow: hidden;\r\n    }\r\n    .img-div img {\r\n        width: 100%;\r\n        transition: 0.5s all ease-in-out;\r\n    }\r\n    .img-div:hover img {\r\n        transform: scale(1.5);\r\n    }', NULL, '2024-10-25 19:13:55', '2024-10-25 19:26:52'),
(5, 5, '<!DOCTYPE html>\r\n<html>\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta name=\"viewport\" \r\n          content=\"width=device-width, initial-scale=1.0\" />\r\n    <title>\r\n        To Zoom an Image on\r\n        Mouse Hover using CSS\r\n    </title>\r\n\r\n</head>\r\n\r\n<body>\r\n    <div class=\"img-div\">\r\n    <img src=\"https://www.w3coderschool.com/attachments/file_1729864290.png\" alt=\"w3coderschool Image\" />\r\n  </div>\r\n</body>\r\n\r\n</html>', 'body {\r\n            text-align: center;\r\n        }\r\n\r\n        .img-div img:hover {\r\n            zoom: 1.2;\r\n        }', NULL, '2024-10-25 19:32:03', '2024-10-25 19:33:41'),
(6, 6, '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <title>iOS 7 Style Toggle Switch Button Using Switchery.js</title>\r\n    <script src=\"https://ajax.googleapis.com/ajax/libs/jquery/1.6.1/jquery.min.js\" type=\"text/javascript\"></script>\r\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/switchery/0.8.2/switchery.min.css\">\r\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/switchery/0.8.2/switchery.min.js\" type=\"text/javascript\"></script>\r\n</head>\r\n<body>\r\n\r\n<input type=\"checkbox\" class=\"js-switch\" checked />\r\n\r\n\r\n</body>\r\n</html>', 'body{\r\ndisplay:flex;\r\nalign-items:center;\r\njustify-content:center;\r\nmin-height:100vh;\r\n}', 'var elem = document.querySelector(\'.js-switch\');\r\n  var init = new Switchery(elem);', '2024-10-25 23:00:34', '2024-11-26 00:07:20'),
(7, 7, '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n    <head>\r\n        <meta charset=\"UTF-8\">\r\n        <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n        <title>Responsive side navigation bar with HTML, CSS, and JavaScript</title>\r\n\r\n    </head>\r\n\r\n    <body>\r\n        <div class=\"nav-bar-div\">\r\n            <ul>\r\n                <li><a href=\"#\">\r\n                        <span class=\"icon\">\r\n                            <ion-icon name=\"home-outline\"></ion-icon>\r\n                        </span>\r\n                        <span class=\"title\">Home</span>\r\n                    </a></li>\r\n                <li><a href=\"#\">\r\n                        <span class=\"icon\">\r\n                            <ion-icon name=\"planet-outline\"></ion-icon>\r\n                        </span>\r\n                        <span class=\"title\">Blog</span>\r\n                    </a></li>\r\n                <li><a href=\"#\">\r\n                        <span class=\"icon\">\r\n                            <ion-icon name=\"logo-facebook\"></ion-icon>\r\n                        </span>\r\n                        <span class=\"title\">facebook</span>\r\n                    </a></li>\r\n            </ul>\r\n            <div class=\"toogle-btn\"></div>\r\n        </div>\r\n\r\n        <script type=\"module\" src=\"https://unpkg.com/ionicons@5.5.2/dist/ionicons/ionicons.esm.js\"></script>\r\n\r\n    </body>\r\n\r\n</html>', '.nav-bar-div {\r\n    position: fixed;\r\n    inset: 20px;\r\n    background: #6c14fa;\r\n    width: 65px;\r\n\r\n    border-radius: 50px;\r\n    overflow: hidden;\r\n    box-shadow: 15px 15px 15px rgba(0, 0, 0, 0.05);\r\n    transition: 0.5s;\r\n}\r\n\r\n.nav-bar-div.active {\r\n    width: 280px;\r\n    border-radius: 20px;\r\n}\r\n\r\n.toogle-btn {\r\n    position: absolute;\r\n    width: 50px;\r\n    height: 50px;\r\n    bottom: 15px;\r\n    right: 8px;\r\n    background-color: white;\r\n    border-radius: 50%;\r\n    box-shadow: 15px 15px 15px rgba(0, 0, 0, 0.05);\r\n    cursor: pointer;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n}\r\n\r\n.toogle-btn::before {\r\n    content: \"\";\r\n    position: absolute;\r\n    width: 26px;\r\n    height: 3px;\r\n    border-radius: 3px;\r\n    background: #365fa1;\r\n    transform: translateY(-5px);\r\n    transition: 1s;\r\n}\r\n\r\n.toogle-btn::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    width: 26px;\r\n    height: 3px;\r\n    border-radius: 3px;\r\n    background: #365fa1;\r\n    transform: translateY(5px);\r\n    transition: 1s;\r\n}\r\n\r\n.nav-bar-div.active .toogle-btn::before {\r\n    transform: translateY(0px) rotate(-405deg);\r\n}\r\n\r\n.nav-bar-div.active .toogle-btn::after {\r\n    transform: translateY(0px) rotate(225deg);\r\n}\r\n\r\n.nav-bar-div ul {\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n}\r\n\r\n.nav-bar-div ul li {\r\n    position: relative;\r\n    list-style: none;\r\n    width: 100%;\r\n}\r\n\r\n.nav-bar-div ul li:hover {\r\n    width: 100%;\r\n}\r\n\r\n.nav-bar-div ul li a {\r\n    position: relative;\r\n    display: block;\r\n    width: 100%;\r\n    color: white;\r\n    display: flex;\r\n    text-decoration: none;\r\n}\r\n\r\n.nav-bar-div ul li a:hover {\r\n    color: #00eeee;\r\n}\r\n\r\n.nav-bar-div ul li:hover:not(:first-child) a {\r\n    color: #00eeee;\r\n}\r\n\r\n.nav-bar-div ul li a .icon {\r\n    position: relative;\r\n    display: block;\r\n    min-width: 60px;\r\n    height: 60px;\r\n    line-height: 70px;\r\n    text-align: center;\r\n}\r\n\r\n.nav-bar-div ul li a .icon ion-icon {\r\n    font-size: 2rem;\r\n    margin-left: -74px;\r\n}\r\n\r\n.nav-bar-div ul li a .title {\r\n    position: relative;\r\n    display: block;\r\n    padding: 0 10px;\r\n    height: 60px;\r\n    line-height: 60px;\r\n    text-align: start;\r\n    white-space: nowrap;\r\n    font-size: 1.5rem;\r\n}', 'let navBarDiv = document.querySelector(\'.nav-bar-div\');\r\nlet toogleBtn = document.querySelector(\'.toogle-btn\');\r\ntoogleBtn.onclick = function () {\r\n    navBarDiv.classList.toggle(\'active\')\r\n}', '2024-10-27 09:49:04', '2024-11-03 17:50:59');
